// src/types/stock.ts
export interface Stock {
  symbol: string;
  name: string;
  exchange: string;
}

export interface StockQuote {
  symbol: string;
  price: number;
  change: number;
  changePercent: number;
  volume: number;
  marketCap: number;
  peRatio?: number;
  high: number;
  low: number;
  open: number;
  previousClose: number;
  timestamp: number;
}

export interface ChartDataPoint {
  timestamp: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

export type TimePeriod = '1D' | '1W' | '1M' | '3M' | '6M' | '1Y' | '5Y';

export interface ChartDataResponse {
  symbol: string;
  period: TimePeriod;
  data: ChartDataPoint[];
}

export interface StockDetails {
  marketCap: number;
  peRatio: number;
  avgVolume: number;
  high52w: number;
  low52w: number;
  eps: number;
  dividend?: number;
  beta?: number;
  sector: string;
  industry: string;
}
```

