// src/server/routes/stock.ts
import { Hono } from 'hono';
import type { StockQuote, ChartDataResponse, StockDetails } from '../../types/stock';

const stockRoutes = new Hono();

// GET /api/stock/:symbol/quote
stockRoutes.get('/:symbol/quote', (c) => {
  const symbol = c.req.param('symbol');
  // Returns: StockQuote
});

// GET /api/stock/:symbol/chart?period=TimePeriod
stockRoutes.get('/:symbol/chart', (c) => {
  const symbol = c.req.param('symbol');
  const period = c.req.query('period') as TimePeriod;
  // Returns: ChartDataResponse
});

// GET /api/stock/:symbol/details
stockRoutes.get('/:symbol/details', (c) => {
  const symbol = c.req.param('symbol');
  // Returns: StockDetails
});

export default stockRoutes;
